INSERT INTO "announcements" VALUES(1,'Scheduled Drinking Water Supply Maintenance','Water Supply','Please note that drinking water supply will be paused in Wards 3, 4, and 5 on Sunday between 10:00 AM and 3:00 PM due to pipeline overhaul. Residents are requested to store adequate water.',0,1,'2026-10-01 18:43:34');
INSERT INTO "announcements" VALUES(2,'Special Swachh Gram Village Cleanliness Drive','Sanitation','The Gram Panchayat is conducting a collective village sanitation drive this Saturday starting at 7:00 AM. Ward members and youth clubs are cordially invited to participate.',0,1,'2026-10-01 18:43:34');
INSERT INTO "announcements" VALUES(3,'Free Medical Health Camp & Pulse Polio Drive','Health','Primary Health Centre (PHC) will host a free health camp and child immunization drive on 15th October at the Gram Panchayat Sabha Bhavan. Doctors will be available from 9 AM to 4 PM.',1,1,'2026-10-01 18:43:34');
INSERT INTO "announcements" VALUES(4,'Ordinary Gram Sabha Meeting Announcement','General Admin','Quarterly Gram Sabha meeting scheduled on October 25th at 10:30 AM to discuss winter crop canal allocations, street lighting expansion, and annual CSP grievance report.',0,1,'2026-10-01 18:43:34');
